<script setup lang="ts">
import { computed } from 'vue'
import { stageNames,milliseconds,outcomeNames,reasonNames,providerTypeNames,type OperationEvent,type TraceDetail } from '../../operations'
import { dateTime } from '../../types'
import Panel from '../../components/ui/Panel.vue'
const props=defineProps<{data:TraceDetail}>()
import { orderedLane } from './timeline'
const lanes=computed(()=>(['desktop','backend'] as const).map(source=>{const events=props.data.events.filter(e=>e.source===source);return{source,items:orderedLane(events),duration:Math.max(1,...events.map(e=>(e.offsetMs??0)+e.durationMs))}}))
</script>
<template><Panel title="操作时间线" class="reveal business-panel" aria-label="操作时间线"><p class="business-code">{{ data.operationId }}</p><p class="business-caption">客户端与后端使用独立单调时钟，泳道内显示相对操作起点。泳道之间不可相减，不推断网络耗时。起始时刻仅用于展示。</p><p v-if="data.partial" class="business-error">链路不完整：可能存在采集关闭、旧客户端、丢弃或已过保留期的阶段。</p><p v-else class="business-caption">当前未标记阶段缺失；仅此标记无法确认全部客户端、后端与渲染阶段均已采集，完整性仍未知。</p><section v-for="lane in lanes" :key="lane.source" class="stack" :aria-label="lane.source==='desktop'?'客户端泳道':'后端泳道'"><h3 class="section-label">{{ lane.source==='desktop'?'客户端报告':'后端测量' }} · 各自起点</h3><p class="business-caption">此泳道范围：0–{{ milliseconds(lane.duration) }}（独立刻度）</p><p v-if="!lane.items.length" class="business-caption">未采集该来源，不代表耗时为零。</p><article v-for="{event,depth} in lane.items" :key="event.eventId" class="operation-span"><div :style="{paddingInlineStart:depth*12+'px'}"><strong>{{ stageNames[event.stage] }}</strong><p class="business-caption">{{ outcomeNames[event.outcome] }} · {{ milliseconds(event.durationMs) }}</p><p class="business-caption">服务：{{ providerTypeNames[event.providerType] }}{{ event.model?` · ${event.model}`:'' }}</p><p class="business-caption">偏移 {{ event.offsetMs===undefined?'未知':milliseconds(event.offsetMs) }} · {{ dateTime(event.startedAt) }}</p><p v-if="event.parentSpanId" class="business-code">父 span：{{ event.parentSpanId }}</p><p v-if="event.reason" class="business-caption">分类：{{ reasonNames[event.reason]??event.reason }}</p><p class="business-code">span：{{ event.spanId }}</p><div v-if="event.metadata" class="business-caption"><span v-for="(value,key) in event.metadata" :key="key">{{ key }}: {{ String(value) }}　</span></div></div><div class="operation-track" :aria-label="`${stageNames[event.stage]}相对耗时条`"><div v-if="event.offsetMs!==undefined" class="operation-bar" :class="{ 'is-error':['error','timeout','rejected'].includes(event.outcome) }" :style="{left:event.offsetMs/lane.duration*100+'%',width:event.durationMs/lane.duration*100+'%'}" /></div></article></section></Panel></template>
